   385	function getPersonalDetailsForAccountIDs(accountIDs: number[] | undefined, personalDetails: OnyxInputOrEntry<PersonalDetailsList>): SetNonNullable<PersonalDetailsList> {
   386	    const personalDetailsForAccountIDs: SetNonNullable<PersonalDetailsList> = {};
   387	    if (!personalDetails) {
   388	        return personalDetailsForAccountIDs;
   389	    }
   390	    accountIDs?.forEach((accountID) => {
   391	        const cleanAccountID = Number(accountID);
   392	        if (!cleanAccountID) {
   393	            return;
   394	        }
   395	        let personalDetail: OnyxEntry<PersonalDetails> = personalDetails[accountID] ?? undefined;
   396	        if (!personalDetail) {
   397	            personalDetail = {} as PersonalDetails;
   398	        }
   399	
   400	        if (cleanAccountID === CONST.ACCOUNT_ID.CONCIERGE) {
   401	            personalDetail.avatar = CONST.CONCIERGE_ICON_URL;
   402	        }
   403	
   404	        personalDetail.accountID = cleanAccountID;
   405	        personalDetailsForAccountIDs[cleanAccountID] = personalDetail;
   406	    });
   407	    return personalDetailsForAccountIDs;
   408	}
